import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo9: HistoricalDocument = {
  id: 'codigo-manu-capitulo-9',
  title: 'Capítulo IX',
  subtitle: 'Do Direito de Família, Herança e Castas',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Trata dos direitos e deveres de marido e mulher, da herança, da propriedade e das obrigações entre castas.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo IX',
      type: 'articles',
      articles: [
        { id: 'cm-9-1', number: 'Verso 1', text: `Declararei agora as leis eternas para um marido e sua esposa que se mantêm no caminho do dever, quer estejam unidos ou separados.` },
        { id: 'cm-9-2', number: 'Verso 2', text: `Dia e noite as mulheres devem ser mantidas em dependência pelos homens de suas (famílias) e, se elas se apegarem aos prazeres sensuais, devem ser mantidas sob controle.` },
        { id: 'cm-9-3', number: 'Verso 3', text: `O seu pai (a) protege na infância, o seu marido (a) protege na juventude, e os seus filhos (a) protegem na velhice; uma mulher nunca é apta para a independência.` },
        { id: 'cm-9-4', number: 'Verso 4', text: `Repreensível é o pai que não dá (sua filha em casamento) no tempo apropriado; repreensível é o marido que não se aproxima (de sua esposa na época devida), e repreensível é o filho que não protege a sua mãe após a morte do seu marido.` },
        { id: 'cm-9-5', number: 'Verso 5', text: `As mulheres devem ser particularmente guardadas contra más inclinações, por mais insignificantes (que possam parecer); pois, se não forem guardadas, trarão tristeza para as duas famílias.` },
        { id: 'cm-9-6', number: 'Verso 6', text: `Considerando que este é o dever mais elevado de todas as castas, mesmo maridos fracos (devem) se esforçar para guardar as suas esposas.` },
        { id: 'cm-9-7', number: 'Verso 7', text: `Aquele que guarda cuidadosamente a sua esposa, preserva (a pureza de) sua prole, a conduta virtuosa, a sua família, a si mesmo e o seu (meio de adquirir) mérito.` },
        { id: 'cm-9-8', number: 'Verso 8', text: `O marido, após a concepção por sua esposa, torna-se um embrião e nasce novamente dela; pois essa é a condição de esposa de uma esposa (*gaya*), que ele nasça (*gayate*) novamente por ela.` },
        { id: 'cm-9-9', number: 'Verso 9', text: `Tal como é o homem a quem uma esposa se apega, assim também é o filho que ela dá à luz; que ele, portanto, guarde cuidadosamente a sua esposa, a fim de manter a sua prole pura.` },
        { id: 'cm-9-10', number: 'Verso 10', text: `Nenhum homem pode guardar as mulheres completamente pela força; mas elas podem ser guardadas pelo emprego dos (seguintes) expedientes:` },
        { id: 'cm-9-11', number: 'Verso 11', text: `Que o (marido) empregue a sua (esposa) na arrecadação e no gasto de sua riqueza, em manter (tudo) limpo, no (cumprimento dos) deveres religiosos, na preparação da sua comida e em cuidar dos utensílios domésticos.` },
        { id: 'cm-9-12', number: 'Verso 12', text: `As mulheres confinadas na casa sob servos de confiança e obedientes não estão (bem) guardadas; mas aquelas que de sua própria vontade se guardam a si mesmas, estão bem guardadas.` },
        { id: 'cm-9-13', number: 'Verso 13', text: `Beber (bebida alcoólica), associar-se a pessoas más, separar-se do marido, vagar por aí, dormir (em horas inoportunas) e morar nas casas de outros homens, são as seis causas da ruína das mulheres.` },
        { id: 'cm-9-14', number: 'Verso 14', text: `As mulheres não se importam com a beleza, nem a sua atenção se fixa na idade; (pensando): '(Basta que) ele seja um homem', elas entregam-se ao bonito e ao feio.` },
        { id: 'cm-9-15', number: 'Verso 15', text: `Através da sua paixão por homens, do seu temperamento mutável, da sua insensibilidade natural, elas tornam-se desleais para com os seus maridos, por mais cuidadosamente que possam ser guardadas neste (mundo).` },
        { id: 'cm-9-16', number: 'Verso 16', text: `Conhecendo a sua disposição, que o Senhor das criaturas colocou nelas na criação, sendo assim, (todo) homem deve esforçar-se da maneira mais enérgica para guardá-las.` },
        { id: 'cm-9-17', number: 'Verso 17', text: `(Ao criá-las) Manu atribuiu às mulheres (um amor à sua) cama, (ao seu) assento e (ao) ornamento, desejos impuros, ira, desonestidade, malícia e má conduta.` },
        { id: 'cm-9-18', number: 'Verso 18', text: `Para as mulheres nenhum rito (sacramental é realizado) com textos sagrados, assim a lei é estabelecida; as mulheres (que são) destituídas de força e destituídas (do conhecimento) dos textos Védicos, (são tão impuras quanto) a própria falsidade, essa é uma regra fixa.` },
        { id: 'cm-9-19', number: 'Verso 19', text: `E com este fim, muitos textos sagrados são cantados também nos Vedas, a fim de (tornar) totalmente conhecida a verdadeira disposição (das mulheres); ouçam (agora os textos que se referem à) expiação dos seus (pecados).` },
        { id: 'cm-9-20', number: 'Verso 20', text: `'Se a minha mãe, desviando-se e infiel, concebeu desejos ilícitos, que o meu pai mantenha essa semente longe de mim', esse é o texto escritural.` },
        { id: 'cm-9-21', number: 'Verso 21', text: `Se uma mulher pensa no seu coração em qualquer coisa que magoaria o seu marido, o (texto acima mencionado) é declarado (ser um meio para) remover completamente tal infidelidade.` },
        { id: 'cm-9-22', number: 'Verso 22', text: `Quaisquer que sejam as qualidades do homem com quem uma mulher se une de acordo com a lei, tais qualidades ela mesma assume, como um rio (unido) ao oceano.` },
        { id: 'cm-9-23', number: 'Verso 23', text: `Akshamala, uma mulher do nascimento mais baixo, sendo unida a Vasishtha e Sarangi, (sendo unida) a Mandapala, tornou-se digna de honra.` },
        { id: 'cm-9-24', number: 'Verso 24', text: `Estas e outras mulheres de baixo nascimento alcançaram eminência neste mundo pelas respectivas boas qualidades dos seus maridos.` },
        { id: 'cm-9-25', number: 'Verso 25', text: `Assim foi declarado o uso popular sempre puro (que regula as relações) entre marido e mulher; ouçam (a seguir) as leis relativas aos filhos que são a causa da felicidade neste mundo e após a morte.` },
        { id: 'cm-9-26', number: 'Verso 26', text: `Entre as esposas (*striyah*) que (são destinadas) a ter filhos, que garantem muitas bênçãos, que são dignas de adoração e irradiam (suas) moradas, e entre as deusas da fortuna (*sriyah*, que residem) nas casas (dos homens), não há diferença alguma.` },
        { id: 'cm-9-27', number: 'Verso 27', text: `A produção de filhos, a criação dos nascidos, e a vida diária dos homens, (dessas questões) a mulher é visivelmente a causa.` },
        { id: 'cm-9-28', number: 'Verso 28', text: `A prole, (o devido desempenho nos ritos religiosos, serviço fiel, a mais alta felicidade conjugal e a bem-aventurança celestial para os ancestrais e para si mesmo, dependem apenas da esposa.` },
        { id: 'cm-9-29', number: 'Verso 29', text: `Aquela que, controlando os seus pensamentos, fala e atos, não viola o seu dever para com o seu senhor, habita com ele (após a morte) no céu, e neste mundo é chamada pelos virtuosos de (esposa) fiel (*sadhvi*).` },
        { id: 'cm-9-30', number: 'Verso 30', text: `Mas por deslealdade para com o seu marido, uma esposa é censurada entre os homens, e (na sua próxima vida) ela nasce no ventre de um chacal e é atormentada por doenças, a punição do seu pecado.` },
        { id: 'cm-9-31', number: 'Verso 31', text: `Ouçam (agora) a seguinte discussão sagrada, salutar para todos os homens, que os virtuosos (do tempo presente) e os antigos grandes sábios mantiveram a respeito da prole masculina.` },
        { id: 'cm-9-32', number: 'Verso 32', text: `Eles (todos) dizem que a descendência masculina (de uma mulher) pertence ao senhor, mas com relação ao (significado do termo) senhor, os textos revelados diferem; alguns chamam o genitor (da criança o senhor), outros declaram (que é) o dono do solo.` },
        { id: 'cm-9-33', number: 'Verso 33', text: `Pela tradição sagrada, a mulher é declarada ser o solo, o homem é declarado ser a semente; a produção de todos os seres corpóreos (ocorre) através da união do solo com a semente.` },
        { id: 'cm-9-34', number: 'Verso 34', text: `Em alguns casos a semente é mais distinguida, e em alguns o ventre da fêmea; mas quando ambos são iguais, a prole é mais altamente estimada.` },
        { id: 'cm-9-35', number: 'Verso 35', text: `Ao comparar a semente e o receptáculo (da semente), a semente é declarada mais importante; pois a prole de todos os seres criados é marcada pelas características da semente.` },
        { id: 'cm-9-36', number: 'Verso 36', text: `Qualquer (tipo de semente semeada num campo, preparado na devida época, (uma planta) desse mesmo tipo, marcada com as qualidades peculiares da semente, brota nele.` },
        { id: 'cm-9-37', number: 'Verso 37', text: `Esta terra, de fato, é chamada o ventre primordial dos seres criados; mas a semente não desenvolve no seu desenvolvimento quaisquer propriedades do ventre.` },
        { id: 'cm-9-38', number: 'Verso 38', text: `Neste mundo, sementes de diferentes tipos, semeadas no tempo adequado na terra, mesmo num único campo, brotam (cada uma) de acordo com o seu tipo.` },
        { id: 'cm-9-39', number: 'Verso 39', text: `O arroz (chamado) *vrihi* e (o chamado) *sali*, feijões *mudga*, gergelim, feijões *masha*, cevada, alho-poró e cana-de-açúcar, (todos) brotam de acordo com a sua semente.` },
        { id: 'cm-9-40', number: 'Verso 40', text: `Que uma (planta) seja semeada e outra seja produzida, não pode acontecer; qualquer que seja a semente semeada, (uma planta) desse mesmo tipo brota.` },
        { id: 'cm-9-41', number: 'Verso 41', text: `Nunca, portanto, um homem prudente e bem treinado, que conhece o Veda e os seus *Angas* e deseja vida longa, deve coabitar com a esposa de outro.` },
        { id: 'cm-9-42', number: 'Verso 42', text: `Com respeito a esta (questão), aqueles familiarizados com o passado recitam algumas estrofes, cantadas por *Vayu* (o Vento, para mostrar) que a semente não deve ser semeada por (nenhum) homem naquilo que pertence a outro.` },
        { id: 'cm-9-43', number: 'Verso 43', text: `Como a flecha atirada por (um caçador) que depois atinge um (veado) ferido na ferida (feita por outro), é atirada em vão, assim também a semente, semeada no que pertence a outro, é rapidamente perdida (para o semeador).` },
        { id: 'cm-9-44', number: 'Verso 44', text: `(Os sábios) que conhecem o passado chamam esta terra (*prithivi*) de esposa de *Prithu*; eles declaram que um campo pertence àquele que limpou a madeira, e um veado àquele que (primeiro) o feriu.` },
        { id: 'cm-9-45', number: 'Verso 45', text: `Apenas ele é um homem perfeito, o qual consiste (em três pessoas unidas), a sua esposa, ele mesmo e a sua prole; assim (diz o Veda), e os *Brahmanas* (eruditos) propõem esta (máxima) da mesma forma: 'O marido é declarado ser um só com a esposa.'` },
        { id: 'cm-9-46', number: 'Verso 46', text: `Nem por venda nem por repúdio uma esposa é libertada do seu marido; tal sabemos ser a lei, que o Senhor das criaturas (*Pragapati*) fez antigamente.` },
        { id: 'cm-9-47', number: 'Verso 47', text: `Uma vez é feita a partilha (da herança), (uma vez) uma donzela é dada em casamento, (e) uma vez (um homem) diz: 'Eu darei'; cada um desses três (atos é feito) apenas uma vez.` },
        { id: 'cm-9-48', number: 'Verso 48', text: `Como com vacas, éguas, camelas fêmeas, escravas, vacas-búfalo, cabras e ovelhas, não é o genitor (ou o seu dono) quem obtém a prole, da mesma forma (acontece) com as esposas dos outros.` },
        { id: 'cm-9-49', number: 'Verso 49', text: `Aqueles que, não tendo propriedade num campo, mas possuindo sementes de grãos, as semeiam no solo de outro, de fato não recebem o grão da colheita que pode brotar.` },
        { id: 'cm-9-50', number: 'Verso 50', text: `Se o touro (de um homem) gerasse cem bezerros nas vacas de outro homem, eles pertenceriam ao dono das vacas; em vão o touro teria gasto a sua força.` },
        { id: 'cm-9-51', number: 'Verso 51', text: `Assim, homens que não têm propriedade conjugal sobre mulheres, mas semeiam a sua semente no solo de outros, beneficiam o dono da mulher; mas o doador da semente não colhe nenhuma vantagem.` },
        { id: 'cm-9-52', number: 'Verso 52', text: `Se nenhum acordo com respeito à colheita foi feito entre o dono do campo e o dono da semente, o benefício claramente pertence ao dono do campo; o receptáculo é mais importante que a semente.` },
        { id: 'cm-9-53', number: 'Verso 53', text: `Mas se por um contrato especial (um campo) é entregue (a outro) para semear, então o dono da semente e o dono do solo são ambos considerados neste mundo como compartilhadores da (colheita).` },
        { id: 'cm-9-54', number: 'Verso 54', text: `Se a semente for levada pela água ou pelo vento para o campo de alguém e germinar (lá), a (planta nascida dessa) semente pertence mesmo ao dono do campo, o dono da semente não recebe a colheita.` },
        { id: 'cm-9-55', number: 'Verso 55', text: `Saiba que tal é a lei a respeito da prole de vacas, éguas, escravas, camelas fêmeas, cabras e ovelhas, bem como de fêmeas de pássaros e búfalas.` },
        { id: 'cm-9-56', number: 'Verso 56', text: `Assim, a importância comparativa da semente e do ventre foi declarada a vós; exporei a seguir a lei (aplicável) às mulheres em tempos de infortúnio.` },
        { id: 'cm-9-57', number: 'Verso 57', text: `A esposa de um irmão mais velho é para o (irmão) mais novo a esposa de um Guru; mas a esposa do mais novo é declarada (ser) a nora do mais velho.` },
        { id: 'cm-9-58', number: 'Verso 58', text: `Um (irmão) mais velho que se aproxima da esposa do mais novo, e um (irmão) mais novo (que se aproxima) da esposa do mais velho, exceto em tempos de infortúnio, ambos tornam-se párias, mesmo que (fossem devidamente) autorizados.` },
        { id: 'cm-9-59', number: 'Verso 59', text: `Na falta de descendência (pelo seu marido), uma mulher que foi autorizada, pode obter, (da) maneira apropriada (prescrita), a prole desejada por (coabitação com) um cunhado ou (com algum outro) *Sapinda* (do marido).` },
        { id: 'cm-9-60', number: 'Verso 60', text: `Ele (que é) nomeado para (coabitar com) a viúva deverá (aproximar-se dela) à noite ungido com manteiga clarificada e em silêncio, (e) gerar um filho, de forma alguma um segundo.` },
        { id: 'cm-9-61', number: 'Verso 61', text: `Alguns (sábios), versados na lei, considerando que o propósito da nomeação não foi alcançado por esses dois (no nascimento do primeiro), acham que um segundo (filho) pode ser legalmente procriado em (tais) mulheres.` },
        { id: 'cm-9-62', number: 'Verso 62', text: `Mas quando o propósito da nomeação para (coabitar com) a viúva tiver sido alcançado de acordo com a lei, esses dois deverão comportar-se um com o outro como pai e nora.` },
        { id: 'cm-9-63', number: 'Verso 63', text: `Se esses dois (sendo assim) nomeados se desviarem da regra e agirem por desejo carnal, ambos tornar-se-ão párias, (como homens) que profanam a cama de uma nora ou de um Guru.` },
        { id: 'cm-9-64', number: 'Verso 64', text: `Por homens duas vezes nascidos, uma viúva não deve ser nomeada para (coabitar com) qualquer outro (além de seu marido); pois aqueles que a nomeiam para outro (homem), violarão a lei eterna.` },
        { id: 'cm-9-65', number: 'Verso 65', text: `Nos textos sagrados que se referem ao casamento, a nomeação (de viúvas) não é mencionada em lugar nenhum, nem o novo casamento de viúvas é prescrito nas regras relativas ao casamento.` },
        { id: 'cm-9-66', number: 'Verso 66', text: `Esta prática que é repreendida pelos eruditos das castas duas vezes nascidas como adequada para gado, diz-se (ter ocorrido) até mesmo entre os homens, enquanto *Vena* governava.` },
        { id: 'cm-9-67', number: 'Verso 67', text: `Aquele chefe dos sábios reais, que outrora possuía o mundo inteiro, causou uma confusão das castas (*varna*), tendo o seu intelecto sido destruído pela luxúria.` },
        { id: 'cm-9-68', number: 'Verso 68', text: `Desde aquele (tempo) os virtuosos censuram aquele (homem) que na sua loucura nomeia uma mulher, cujo marido morreu, para (dar) filhos (a outro homem).` },
        { id: 'cm-9-69', number: 'Verso 69', text: `Se o (futuro) marido de uma donzela morre após a promessa verbal, o seu cunhado a desposará de acordo com a seguinte regra.` },
        { id: 'cm-9-70', number: 'Verso 70', text: `Tendo, de acordo com a regra, desposado ela (que deve estar) vestida com roupas brancas e focada na pureza, ele aproximar-se-á dela uma vez em cada estação apropriada até que se tenha prole.` },
        { id: 'cm-9-71', number: 'Verso 71', text: `Que nenhum homem prudente, depois de dar a sua filha a um (homem), a dê novamente a outro; pois aquele que dá (a sua filha) a quem já havia dado antes, incorre (na culpa de) falar falsamente a respeito de um ser humano.` },
        { id: 'cm-9-72', number: 'Verso 72', text: `Embora (um homem) possa ter aceitado uma donzela na devida forma, ele pode abandoná-la (se ela estiver) manchada, doente ou desflorada, e (se tiver sido) dada com fraude.` },
        { id: 'cm-9-73', number: 'Verso 73', text: `Se alguém entrega uma donzela que possui manchas sem declará-las, (o noivo) pode anular aquele (contrato) com o doador de má índole.` },
        { id: 'cm-9-74', number: 'Verso 74', text: `Um homem que tenha negócios (no exterior) pode partir depois de garantir o sustento para a sua esposa; pois uma esposa, mesmo sendo virtuosa, pode ser corrompida se estiver angustiada pela falta de subsistência.` },
        { id: 'cm-9-75', number: 'Verso 75', text: `Se (o marido) fez uma viagem depois de providenciar (para ela), a esposa sujeitar-se-á a restrições na sua vida diária; mas se ele partiu sem providenciar (para ela), ela pode subsistir de trabalho manual irrepreensível.` },
        { id: 'cm-9-76', number: 'Verso 76', text: `Se o marido foi para o exterior por algum dever sagrado, (ela) deve esperar por ele oito anos, se (ele foi) para (adquirir) conhecimento ou fama seis (anos), se (ele foi) por prazer três anos.` },
        { id: 'cm-9-77', number: 'Verso 77', text: `Por um ano que um marido suporte uma esposa que o odeia; mas depois de (decorrido) um ano, que ele a prive das suas propriedades e deixe de coabitar com ela.` },
        { id: 'cm-9-78', number: 'Verso 78', text: `Aquela que mostra desrespeito a (um marido) que é viciado em (alguma má) paixão, é um bêbado ou doente, será abandonada por três meses (e será) privada dos seus ornamentos e mobília.` },
        { id: 'cm-9-79', number: 'Verso 79', text: `Mas aquela que mostra aversão a um marido louco ou pária, a um eunuco, a alguém destituído de força viril, ou a alguém afligido por tais doenças que punem os crimes, não será nem rejeitada nem privada das suas propriedades.` },
        { id: 'cm-9-80', number: 'Verso 80', text: `Aquela que bebe bebida alcoólica, é de má conduta, rebelde, doente, maliciosa ou gastadora, pode a qualquer momento ser substituída (por outra esposa).` },
        { id: 'cm-9-81', number: 'Verso 81', text: `Uma esposa estéril pode ser substituída no oitavo ano, aquela cujos filhos (todos) morrem no décimo, aquela que só tem filhas no décimo primeiro, mas a que é briguenta sem demora.` },
        { id: 'cm-9-82', number: 'Verso 82', text: `Mas uma esposa doente que é gentil (para com o seu marido) e virtuosa na sua conduta, pode ser substituída (apenas) com o seu próprio consentimento e nunca deve ser desgraçada.` },
        { id: 'cm-9-83', number: 'Verso 83', text: `Uma esposa que, sendo substituída, parte da casa (do marido) com raiva, deve ser instantaneamente confinada ou rejeitada na presença da família.` },
        { id: 'cm-9-84', number: 'Verso 84', text: `Mas aquela que, embora tendo sido proibida, bebe bebida alcoólica mesmo em festivais, ou vai a espetáculos ou assembleias públicas, será multada em seis *krishnalas*.` },
        { id: 'cm-9-85', number: 'Verso 85', text: `Se homens duas vezes nascidos desposam mulheres de sua própria e de outras (castas inferiores), a antiguidade, honra e habitação daquelas (esposas) devem ser (estabelecidas) de acordo com a ordem das castas (*varna*).` },
        { id: 'cm-9-86', number: 'Verso 86', text: `Entre todos (os homens duas vezes nascidos) a esposa de igual casta apenas, não uma esposa de uma casta diferente de forma alguma, deverá pessoalmente atender o seu marido e assisti-lo nos seus ritos sagrados diários.` },
        { id: 'cm-9-87', number: 'Verso 87', text: `Mas aquele que tolamente faz com que esse (dever) seja executado por outra, enquanto a sua esposa de igual casta está viva, é declarado pelos antigos (ser) tão (desprezível) quanto um *Kandala* (nascido da) (casta) *Brahmana*.` },
        { id: 'cm-9-88', number: 'Verso 88', text: `A um pretendente distinto e bonito (de) (casta) igual deveria (um pai) dar a sua filha de acordo com a regra prescrita, embora ela não tenha atingido (a idade apropriada).` },
        { id: 'cm-9-89', number: 'Verso 89', text: `(Mas) a donzela, embora em idade de casar, deveria antes permanecer na casa (do pai) até à morte, do que ele jamais dar-lhe-ia a um homem destituído de boas qualidades.` },
        { id: 'cm-9-90', number: 'Verso 90', text: `Três anos que uma donzela espere, embora esteja em idade de casar; mas depois desse tempo que ela escolha por si mesma um noivo (de) (casta e posição) igual.` },
        { id: 'cm-9-91', number: 'Verso 91', text: `Se, não sendo dada em casamento, ela própria procura um marido, não incorre em culpa, nem (incorre) aquele com quem ela se casa.` },
        { id: 'cm-9-92', number: 'Verso 92', text: `Uma donzela que escolhe para si mesma não deverá levar consigo nenhum ornamento, dado por seu pai ou sua mãe, ou seus irmãos; se ela os levar embora, será roubo.` },
        { id: 'cm-9-93', number: 'Verso 93', text: `Mas aquele que toma (por esposa) uma donzela em idade de casar, não pagará nenhuma taxa nupcial ao pai dela; pois o (último) perderá o seu domínio sobre ela em consequência de ter impedido (o resultado legítimo do aparecimento de) seus inimigos.` },
        { id: 'cm-9-94', number: 'Verso 94', text: `Um homem, aos trinta anos de idade, deverá casar com uma donzela de doze anos que lhe agrade, ou um homem de vinte e quatro anos com uma menina de oito anos de idade; se (o cumprimento dos) seus deveres (de outro modo) fosse impedido, (ele deve casar) mais cedo.` },
        { id: 'cm-9-95', number: 'Verso 95', text: `O marido recebe a sua esposa dos deuses, (ele não a desposa) de acordo com a sua própria vontade; fazendo o que é agradável aos deuses, ele deve sempre sustentá-la (enquanto ela for) fiel.` },
        { id: 'cm-9-96', number: 'Verso 96', text: `Para serem mães as mulheres foram criadas, e para serem pais os homens; os ritos religiosos, portanto, são ordenados no Veda para serem realizados (pelo marido) juntamente com a esposa.` },
        { id: 'cm-9-97', number: 'Verso 97', text: `Se, depois que a taxa nupcial tiver sido paga por uma donzela, o doador da taxa morrer, ela será dada em casamento ao irmão dele, caso ela consinta.` },
        { id: 'cm-9-98', number: 'Verso 98', text: `Nem mesmo um *Sudra* deveria receber uma taxa nupcial ao entregar a sua filha; pois aquele que recebe uma taxa vende a sua filha, encobrindo (a transação sob outro nome).` },
        { id: 'cm-9-99', number: 'Verso 99', text: `Nem os antigos nem os modernos que eram homens bons fizeram tal (ação) que, depois de prometer (uma filha) a um homem, eles a deram a outro;` },
        { id: 'cm-9-100', number: 'Verso 100', text: `Nem, de fato, ouvimos, mesmo em criações anteriores, de tal (coisa como) a venda encoberta de uma filha por um preço fixo, chamado de taxa nupcial.` },
        { id: 'cm-9-101', number: 'Verso 101', text: `'Que a fidelidade mútua continue até à morte', isto pode ser considerado como o resumo da mais alta lei para marido e mulher.` },
        { id: 'cm-9-102', number: 'Verso 102', text: `Que o homem e a mulher, unidos em matrimônio, se esforcem constantemente para que (não sejam) desunidos (e) não violem a sua fidelidade mútua.` },
        { id: 'cm-9-103', number: 'Verso 103', text: `Assim foi declarada a vós a lei para um marido e a sua esposa, que está intimamente ligada à felicidade conjugal, e a maneira de criar prole em tempos de calamidade; aprendam (agora a lei a respeito) da divisão da herança.` },
        { id: 'cm-9-104', number: 'Verso 104', text: `Após a morte do pai e da mãe, os irmãos, reunidos, podem dividir entre si em partes iguais a propriedade paterna (e a materna); pois não têm poder (sobre ela) enquanto os pais viverem.` },
        { id: 'cm-9-105', number: 'Verso 105', text: `(Ou) o mais velho sozinho pode tomar toda a propriedade paterna, e os outros viverão sob ele tal como (viveram) sob o seu pai.` },
        { id: 'cm-9-106', number: 'Verso 106', text: `Imediatamente após o nascimento do seu primogênito, um homem é (chamado) pai de um filho e é libertado da dívida para com os manes; esse (filho), portanto, é digno de (receber) toda a propriedade.` },
        { id: 'cm-9-107', number: 'Verso 107', text: `Aquele filho único sobre o qual ele lança a sua dívida e através de quem ele obtém a imortalidade, é gerado para (o cumprimento da) lei; todos os demais eles consideram prole do desejo.` },
        { id: 'cm-9-108', number: 'Verso 108', text: `Como um pai (sustenta) os seus filhos, assim que o mais velho sustente os seus irmãos mais novos, e que eles também, de acordo com a lei, se comportem com o seu irmão mais velho como filhos (se comportam com o seu pai).` },
        { id: 'cm-9-109', number: 'Verso 109', text: `O (filho) mais velho torna a família próspera ou, pelo contrário, leva-a à ruína; o mais velho (é considerado) entre os homens como o mais digno de honra, o mais velho não é tratado com desrespeito pelos virtuosos.` },
        { id: 'cm-9-110', number: 'Verso 110', text: `Se o irmão mais velho se comporta como um irmão mais velho (deveria), ele (deve ser tratado) como uma mãe e como um pai; mas se ele se comporta de uma maneira indigna de um irmão mais velho, ainda assim ele deve ser honrado como um parente.` },
        { id: 'cm-9-111', number: 'Verso 111', text: `Que eles vivam assim juntos ou separados, se (cada um) desejar (ganhar) mérito espiritual; pois (ao viverem) separados (o seu) mérito aumenta, portanto a separação é meritória.` },
        { id: 'cm-9-112', number: 'Verso 112', text: `A parte adicional (deduzida) para o mais velho será um vigésimo (da propriedade) e o melhor de todos os bens móveis, para o do meio metade disso, mas para o mais novo um quarto.` },
        { id: 'cm-9-113', number: 'Verso 113', text: `Tanto o mais velho quanto o mais novo tomarão (as suas partes) de acordo com (a regra que acabamos de) afirmar (cada um dos) que estão entre o mais velho e o mais novo, terá a parte (prescrita para o) do meio.` },
        { id: 'cm-9-114', number: 'Verso 114', text: `Entre os bens de todo tipo, o mais velho tomará o melhor (artigo), e (mesmo um único bem) que seja particularmente bom, bem como o melhor de dez (animais).` },
        { id: 'cm-9-115', number: 'Verso 115', text: `Mas entre (irmãos) igualmente hábeis nas suas ocupações, não há parte adicional, (consistindo no melhor animal) entre dez; alguma insignificância apenas será dada ao mais velho como um sinal de respeito.` },
        { id: 'cm-9-116', number: 'Verso 116', text: `Se as partes adicionais forem assim deduzidas, devem-se alocar partes iguais (do restante para cada um); mas se nenhuma dedução for feita, a atribuição das partes entre eles será (feita) da seguinte maneira.` },
        { id: 'cm-9-117', number: 'Verso 117', text: `Que o filho mais velho pegue uma parte em excesso, o (irmão) nascido logo depois dele uma (parte) e meia, os mais novos uma parte cada; assim a lei está estabelecida.` },
        { id: 'cm-9-118', number: 'Verso 118', text: `Mas para as (irmãs) donzelas os irmãos deverão dar individualmente (porções) de suas partes, cada um de sua parte uma quarta parte; aqueles que se recusarem a dar (isso), tornar-se-ão párias.` },
        { id: 'cm-9-119', number: 'Verso 119', text: `Que ele nunca divida (o valor de) uma única cabra ou ovelha, ou um (único animal) com cascos não fendidos; é prescrito (que) uma única cabra ou ovelha (remanescente após uma divisão igual, pertença) somente ao mais velho.` },
        { id: 'cm-9-120', number: 'Verso 120', text: `Se um irmão mais novo gerar um filho com a esposa do mais velho, a divisão deverá então ser feita igualmente; assim a lei está estabelecida.` },
        { id: 'cm-9-121', number: 'Verso 121', text: `O representante (o filho gerado na esposa) não é investido do direito do principal (o irmão mais velho a uma parte adicional); o principal (tornou-se) um pai na procriação (de um filho pelo seu irmão mais novo); daí, deve-se dar uma parte ao (filho gerado na esposa do irmão mais velho) de acordo com a regra (afirmada acima).` },
        { id: 'cm-9-122', number: 'Verso 122', text: `Se houver dúvida, sobre como a divisão deverá ser feita, caso o filho mais novo nasça da esposa mais velha e o filho mais velho da esposa mais nova,` },
        { id: 'cm-9-123', number: 'Verso 123', text: `(Então o filho) nascido da primeira esposa tomará como a sua parte adicional um touro (mais excelente); os próximos melhores touros (pertencerão) àqueles (que são) inferiores por conta das suas mães.` },
        { id: 'cm-9-124', number: 'Verso 124', text: `Mas o (filho) mais velho, (sendo) nascido da esposa mais velha, receberá quinze vacas e um touro, os outros filhos poderão então tomar as partes de acordo com (a antiguidade de) suas mães; essa é uma regra estabelecida.` },
        { id: 'cm-9-125', number: 'Verso 125', text: `Entre os filhos nascidos de esposas iguais (em casta) (e) sem (qualquer outra) distinção não existe prioridade por direito da mãe; a antiguidade é declarada (ser) de acordo com o nascimento.` },
        { id: 'cm-9-126', number: 'Verso 126', text: `E com respeito aos (textos) *Subrahmanya* também é registrado que a invocação (de Indra será feita) pelo primogênito, dos gêmeos da mesma forma, (concebidos ao mesmo tempo) nos ventres (de suas mães), a antiguidade é declarada (depender) do nascimento (real).` },
        { id: 'cm-9-127', number: 'Verso 127', text: `Aquele que não tem filho pode tornar a sua filha da seguinte maneira uma filha nomeada (*putrika*, dizendo ao seu marido): 'A criança (masculina), nascida dela, deverá realizar os meus ritos fúnebres.'` },
        { id: 'cm-9-128', number: 'Verso 128', text: `De acordo com esta regra Daksha, ele próprio, senhor dos seres criados, outrora fez de (todas as suas descendentes femininas) filhas nomeadas a fim de multiplicar a sua raça.` },
        { id: 'cm-9-129', number: 'Verso 129', text: `Ele deu dez a Dharma, treze a Kasyapa, vinte e sete ao Rei Soma, honrando-(as) com um coração afetuoso.` },
        { id: 'cm-9-130', number: 'Verso 130', text: `Um filho é o mesmo (que) a si mesmo, (tal) filha é igual a um filho; como pode outro (herdeiro) tomar a propriedade, enquanto tal (filha nomeada que é até mesmo) ele mesmo, vive?` },
        { id: 'cm-9-131', number: 'Verso 131', text: `Mas seja qual for a propriedade separada da mãe, essa é a parte apenas da filha solteira; e o filho de uma filha (nomeada) tomará toda a propriedade (do seu avô materno) que não deixa nenhum filho.` },
        { id: 'cm-9-132', number: 'Verso 132', text: `O filho de uma filha (nomeada), de fato, deverá (também) tomar a propriedade do seu (próprio) pai, que não deixa (nenhum) outro filho; ele deverá (então) apresentar dois bolos fúnebres, um ao seu próprio pai e outro ao seu avô materno.` },
        { id: 'cm-9-133', number: 'Verso 133', text: `Entre o filho de um filho e o filho de uma filha (nomeada) não há diferença, nem em relação aos assuntos mundanos nem aos deveres sagrados; pois o pai e a mãe de ambos brotaram do corpo do mesmo (homem).` },
        { id: 'cm-9-134', number: 'Verso 134', text: `Mas se, depois que uma filha for nomeada, um filho nascer (para o pai dela), a divisão (da herança) deverá nesse (caso) ser igual; pois não há direito de primogenitura para uma mulher.` },
        { id: 'cm-9-135', number: 'Verso 135', text: `Mas se uma filha nomeada morrer por acidente sem (deixar) um filho, o marido da filha nomeada pode, sem hesitação, tomar aquela propriedade.` },
        { id: 'cm-9-136', number: 'Verso 136', text: `Por meio daquele filho que (uma filha), não nomeada ou nomeada, venha a dar a (um marido) de (casta) igual, o seu avô materno (tem) o filho de um filho; ele deverá apresentar o bolo fúnebre e ficar com a propriedade.` },
        { id: 'cm-9-137', number: 'Verso 137', text: `Por meio de um filho ele conquista os mundos, por meio do filho de um filho ele obtém a imortalidade, mas por meio do neto do seu filho ele ganha o mundo do sol.` },
        { id: 'cm-9-138', number: 'Verso 138', text: `Porque um filho livra (*trayate*) o seu pai do inferno chamado *Put*, ele foi, portanto, chamado de *put-tra* (um libertador de *Put*) pelo próprio Auto-existente (*Svayambhu*).` },
        { id: 'cm-9-139', number: 'Verso 139', text: `Entre o filho de um filho e o filho de uma filha não existe neste mundo nenhuma diferença; pois até mesmo o filho de uma filha salva aquele (que não tem filhos) no próximo mundo, como o filho do filho.` },
        { id: 'cm-9-140', number: 'Verso 140', text: `Que o filho de uma filha nomeada apresente primeiro um bolo fúnebre para sua mãe, o segundo para o pai dela, o funeral para o pai de seu pai.` },
        { id: 'cm-9-141', number: 'Verso 141', text: `Do homem que tem um filho adotivo (*Datrima*) possuindo todas as boas qualidades, esse mesmo (filho) deverá tomar a herança, embora trazido de outra família.` },
        { id: 'cm-9-142', number: 'Verso 142', text: `Um filho adotivo nunca tomará o (nome) da família e a propriedade do seu pai biológico; o bolo fúnebre acompanha o (nome) da família e a propriedade, as oferendas fúnebres daquele que dá (o seu filho em adoção) cessam (no que diz respeito a esse filho).` },
        { id: 'cm-9-143', number: 'Verso 143', text: `O filho de uma esposa, não nomeada (para ter descendência por outro), e aquele que (uma fêmea nomeada, já) a mãe de um filho, dá ao seu cunhado, são ambos indignos de uma parte, (sendo um) o filho de um adúltero e (o outro) produzido por meio da (mera) luxúria.` },
        { id: 'cm-9-144', number: 'Verso 144', text: `Mesmo a (criança) masculina de uma fêmea (devidamente) nomeada, não gerada de acordo com a regra (dada acima), é indigna da propriedade paterna; pois foi procriada por um pária.` },
        { id: 'cm-9-145', number: 'Verso 145', text: `Um filho (legalmente) gerado em tal fêmea nomeada deverá herdar como um filho legítimo do corpo; pois essa semente e o produto pertencem, de acordo com a lei, ao dono do solo.` },
        { id: 'cm-9-146', number: 'Verso 146', text: `Aquele que cuida da propriedade do seu irmão falecido e da sua viúva, deverá, após criar um filho para o seu irmão, dar aquela propriedade àquele (filho).` },
        { id: 'cm-9-147', number: 'Verso 147', text: `Se uma mulher (devidamente) nomeada der um filho ao seu cunhado ou a outro (*Sapinda*), afirmam que aquele (filho, se ele é) gerado através do desejo, é incapaz de herdar e que foi produzido em vão.` },
        { id: 'cm-9-148', number: 'Verso 148', text: `As regras (dadas acima) devem ser entendidas como (aplicáveis) a uma distribuição entre filhos de mulheres da mesma (casta); ouçam (agora a lei) sobre os gerados por um homem em muitas esposas de diferentes (castas).` },
        { id: 'cm-9-149', number: 'Verso 149', text: `Se houver quatro esposas de um *Brahmana* na ordem direta das castas, a regra para a divisão (da propriedade) entre os filhos nascidos delas é a seguinte:` },
        { id: 'cm-9-150', number: 'Verso 150', text: `O (escravo) que cultiva (o campo), o touro mantido para engravidar vacas, o veículo, os ornamentos e a casa serão dados como uma porção adicional ao (filho) *Brahmana*, e uma parte mais excelente.` },
        { id: 'cm-9-151', number: 'Verso 151', text: `Que o filho da (esposa) *Brahmana* tome três partes (do restante) da propriedade, o filho da *Kshatriya* duas, o filho da *Vaisya* uma parte e meia, e o filho da *Sudra* pode tomar uma parte.` },
        { id: 'cm-9-152', number: 'Verso 152', text: `Ou que aquele que conhece a lei faça dez partes de toda a propriedade e as distribua justamente de acordo com a seguinte regra:` },
        { id: 'cm-9-153', number: 'Verso 153', text: `O (filho) *Brahmana* tomará quatro partes, o filho da (esposa) *Kshatriya* três, o filho da *Vaisya* terá duas partes, o filho da *Sudra* poderá tomar uma parte.` },
        { id: 'cm-9-154', number: 'Verso 154', text: `Quer (um *Brahmana*) tenha filhos ou não tenha filhos (por esposas das castas duas vezes nascidas), o (herdeiro) deve, de acordo com a lei, dar ao filho de uma (esposa) *Sudra* não mais que uma décima (parte da sua propriedade).` },
        { id: 'cm-9-155', number: 'Verso 155', text: `O filho de um *Brahmana*, de um *Kshatriya* e de um *Vaisya* por uma (esposa) *Sudra* não recebe nenhuma parte da herança; o que quer que o seu pai possa dar-lhe, será de sua propriedade.` },
        { id: 'cm-9-156', number: 'Verso 156', text: `Todos os filhos de homens duas vezes nascidos, nascidos de esposas da mesma casta, deverão dividir igualmente a propriedade, depois que os outros tiverem dado ao mais velho uma parte adicional.` },
        { id: 'cm-9-157', number: 'Verso 157', text: `Pois a um *Sudra* é ordenada uma esposa de sua própria casta apenas (e) nenhuma outra; os nascidos dela terão partes iguais, mesmo que haja cem filhos.` },
        { id: 'cm-9-158', number: 'Verso 158', text: `Entre os doze filhos de homens que Manu, nascido do Auto-existente (*Svayambhu*), enumera, seis são parentes e herdeiros, e seis não são herdeiros, (mas) parentes.` },
        { id: 'cm-9-159', number: 'Verso 159', text: `O filho legítimo do corpo, o filho gerado numa esposa, o filho adotivo, o filho feito, o filho nascido secretamente, e o filho rejeitado, (são) os seis herdeiros e parentes.` },
        { id: 'cm-9-160', number: 'Verso 160', text: `O filho de uma donzela solteira, o filho recebido com a esposa, o filho comprado, o filho gerado numa mulher recasada, o filho dado por si mesmo, e o filho de uma fêmea *Sudra*, (são) os seis (que) não (são) herdeiros, (mas) parentes.` },
        { id: 'cm-9-161', number: 'Verso 161', text: `Qualquer que seja o resultado que obtenha um homem que (tenta) cruzar uma (massa de) água num barco inseguro, esse mesmo resultado obtém aquele que (tenta) passar a escuridão (do outro mundo) com (a ajuda de) maus (substitutos para um) filho (real).` },
        { id: 'cm-9-162', number: 'Verso 162', text: `Se os dois herdeiros de um homem forem um filho legítimo do seu corpo e um filho gerado na sua esposa, cada um (dos dois filhos), com exclusão do outro, tomará a propriedade do seu pai (biológico).` },
        { id: 'cm-9-163', number: 'Verso 163', text: `Apenas o filho legítimo do corpo (será) o dono da propriedade paterna; mas, a fim de evitar a dureza, que ele permita um sustento aos demais.` },
        { id: 'cm-9-164', number: 'Verso 164', text: `Mas quando o filho legítimo do corpo divide a propriedade paterna, ele deverá dar uma sexta ou uma quinta parte da propriedade do seu pai ao filho gerado na esposa.` },
        { id: 'cm-9-165', number: 'Verso 165', text: `O filho legítimo e o filho da esposa partilham (assim) a propriedade do pai; mas os outros tornar-se-ão membros da família e herdarão de acordo com a sua ordem (cada um nomeado posteriormente na falta dos nomeados anteriormente).` },
        { id: 'cm-9-166', number: 'Verso 166', text: `Aquele que um homem gera na sua própria esposa casada, que ele saiba ser um filho legítimo do corpo (*Aurasa*), o primeiro na hierarquia.` },
        { id: 'cm-9-167', number: 'Verso 167', text: `Aquele que foi gerado de acordo com a lei peculiar (do *Niyoga*) na esposa nomeada de um homem morto, de um eunuco ou de um doente, é chamado de filho gerado numa esposa (*Kshetraga*).` },
        { id: 'cm-9-168', number: 'Verso 168', text: `Aquele (menino) igual (por casta) que a sua mãe ou o seu pai afetuosamente dão, (confirmando a doação) com (uma libação de) água, em tempos de angústia (a um homem) como o seu filho, deve ser considerado como um filho adotivo (*Datrima*).` },
        { id: 'cm-9-169', number: 'Verso 169', text: `Mas é considerado um filho feito (*Kritrima*) aquele que (um homem) faz seu filho, (sendo ele) igual (por casta), familiarizado com (as distinções entre) o certo e o errado, (e) dotado de virtudes filiais.` },
        { id: 'cm-9-170', number: 'Verso 170', text: `Se (uma criança) nascer na casa de um homem e o seu pai não for conhecido, ele é um filho nascido secretamente na casa (*Gudhotpanna*), e pertencerá àquele de cuja esposa ele nasceu.` },
        { id: 'cm-9-171', number: 'Verso 171', text: `Aquele que (um homem) recebe como seu filho, (depois de ter sido) abandonado pelos seus pais ou por um deles, é chamado de filho rejeitado (*Apaviddha*).` },
        { id: 'cm-9-172', number: 'Verso 172', text: `Um filho que uma donzela tem secretamente na casa do seu pai, chamar-se-á o filho de uma donzela solteira (*Kanina*, e declarará) tal prole de uma garota solteira (como pertencente) àquele que a desposa (depois).` },
        { id: 'cm-9-173', number: 'Verso 173', text: `Se alguém se casa, consciente ou inconscientemente, com uma (noiva) grávida, a criança no seu ventre pertence àquele que a desposa, e é chamado (um filho) recebido com a noiva (*Sahodha*).` },
        { id: 'cm-9-174', number: 'Verso 174', text: `Se um homem compra um (menino), seja igual ou desigual (em boas qualidades), do seu pai e da sua mãe com o propósito de ter um filho, essa (criança) é chamada de (filho) comprado (*Kritaka*).` },
        { id: 'cm-9-175', number: 'Verso 175', text: `Se uma mulher abandonada pelo seu marido, ou uma viúva, de sua própria vontade contrai um segundo casamento e tem (um filho), ele é chamado de filho de uma mulher recasada (*Paunarbhava*).` },
        { id: 'cm-9-176', number: 'Verso 176', text: `Se ela for (ainda) virgem, ou alguém que retornou (ao seu primeiro marido) depois de deixá-lo, ela é digna de realizar novamente com o seu segundo (ou primeiro marido abandonado) a cerimônia (nupcial).` },
        { id: 'cm-9-177', number: 'Verso 177', text: `Aquele que, tendo perdido os seus pais ou sendo abandonado (por eles) sem causa (justa), se entrega a um (homem), é chamado de filho dado por si mesmo (*Svayamdatta*).` },
        { id: 'cm-9-178', number: 'Verso 178', text: `O filho que um *Brahmana* gera por luxúria numa fêmea *Sudra* é, (embora) vivo (*parayan*), um cadáver (*sava*), e por isso chamado de *Parasava* (um cadáver vivo).` },
        { id: 'cm-9-179', number: 'Verso 179', text: `Um filho que é (gerado) por um *Sudra* numa escrava, ou na escrava do seu escravo, pode, se permitido (pelo seu pai), tomar uma parte (da herança); assim a lei está estabelecida.` },
        { id: 'cm-9-180', number: 'Verso 180', text: `Estes onze, o filho gerado na esposa e os restantes conforme enumerados (acima), os sábios chamam de substitutos de um filho, (tomados) a fim (de evitar) a falha das cerimônias (fúnebres).` },
        { id: 'cm-9-181', number: 'Verso 181', text: `Aqueles filhos, que foram mencionados em conexão com (o filho legítimo do corpo), sendo gerados por estranhos, pertencem (na realidade) àquele de cuja semente eles brotaram, mas não ao outro (homem que os tomou).` },
        { id: 'cm-9-182', number: 'Verso 182', text: `Se entre irmãos, nascidos de um (pai), um tiver um filho, Manu declarou que todos eles têm prole masculina através daquele filho.` },
        { id: 'cm-9-183', number: 'Verso 183', text: `Se entre todas as esposas de um marido uma tiver um filho, Manu declara que todas elas (são) mães de filhos homens através daquele filho.` },
        { id: 'cm-9-184', number: 'Verso 184', text: `Na falta de cada filho melhor, cada (um) inferior seguinte é digno da herança; mas se houver muitos (de) hierarquia igual, todos partilharão a propriedade.` },
        { id: 'cm-9-185', number: 'Verso 185', text: `Nem irmãos, nem pais, (mas) os filhos tomam a propriedade paterna; mas o pai tomará a herança de (um filho) que não deixa descendência masculina, e os seus irmãos.` },
        { id: 'cm-9-186', number: 'Verso 186', text: `A três (ancestrais) a água deve ser oferecida, a três o bolo fúnebre é dado, o quarto (descendente é) o doador dessas (oblações), o quinto não tem conexão (com eles).` },
        { id: 'cm-9-187', number: 'Verso 187', text: `Sempre àquele (parente dentro de três graus) que for o mais próximo do *Sapinda* (falecido) a propriedade pertencerá; depois um *Sakulya* será (o herdeiro, então) o professor espiritual ou o pupilo.` },
        { id: 'cm-9-188', number: 'Verso 188', text: `Mas na falta de todos (os herdeiros) os *Brahmanas* (deverão) partilhar a propriedade, (os que são) versados nos três Vedas, puros e autocontrolados; assim a lei não é violada.` },
        { id: 'cm-9-189', number: 'Verso 189', text: `A propriedade de um *Brahmana* nunca deve ser tomada pelo rei, essa é uma regra estabelecida; mas (a propriedade de homens) de outras castas o rei pode tomar na falta de todos (os herdeiros).` },
        { id: 'cm-9-190', number: 'Verso 190', text: `(Se a viúva) de (um homem) que morreu sem deixar descendência, criar para ele um filho por um membro da família (*Sagotra*), ela deverá entregar àquele (filho) toda a propriedade que pertencia ao (falecido).` },
        { id: 'cm-9-191', number: 'Verso 191', text: `Mas se dois (filhos), gerados por dois (homens diferentes), disputarem a propriedade (nas mãos) de sua mãe, cada um tomará, com exclusão do outro, o que pertencia ao seu pai.` },
        { id: 'cm-9-192', number: 'Verso 192', text: `Mas quando a mãe morrer, todos os irmãos uterinos e as irmãs uterinas deverão dividir igualmente a propriedade da mãe.` },
        { id: 'cm-9-193', number: 'Verso 193', text: `Até mesmo às filhas daquelas (filhas) algo deve ser dado, como for conveniente, da propriedade de sua avó materna, por motivo de afeição.` },
        { id: 'cm-9-194', number: 'Verso 194', text: `O que (foi dado) diante do fogo (nupcial), o que (foi dado) na procissão nupcial, o que foi dado como prova de amor, e o que foi recebido de seu irmão, mãe ou pai, isso é chamado a propriedade sêxtupla de uma mulher.` },
        { id: 'cm-9-195', number: 'Verso 195', text: `(Tal propriedade), bem como um presente subsequente e o que foi dado (a ela) pelo seu marido afetuoso, irá para a sua prole, (mesmo) se ela morrer durante a vida de seu marido.` },
        { id: 'cm-9-196', number: 'Verso 196', text: `É ordenado que a propriedade (de uma mulher casada) de acordo com o rito *Brahma*, *Daiva*, *Arsha*, *Gandharva* ou *Pragapatya* (pertencerá) somente ao seu marido, se ela morrer sem descendência.` },
        { id: 'cm-9-197', number: 'Verso 197', text: `Mas é prescrito que a propriedade que pode ter sido dada a uma (esposa) num casamento *Asura* ou (um dos) outros (casamentos censuráveis, irá) para a sua mãe e para o seu pai, se ela morrer sem descendência.` },
        { id: 'cm-9-198', number: 'Verso 198', text: `Qualquer propriedade que possa ter sido dada pelo seu pai a uma esposa (que tem co-esposas de castas diferentes), isso a filha da (esposa) *Brahmani* tomará, ou a descendência dessa (filha).` },
        { id: 'cm-9-199', number: 'Verso 199', text: `As mulheres nunca devem fazer um tesouro escondido com (a propriedade de) suas famílias que é comum a muitos, nem com a sua própria propriedade (particular dos maridos) sem permissão.` },
        { id: 'cm-9-200', number: 'Verso 200', text: `Os ornamentos que podem ter sido usados pelas mulheres durante a vida dos seus maridos, os herdeiros dele não dividirão; aqueles que os dividirem tornam-se párias.` },
        { id: 'cm-9-201', number: 'Verso 201', text: `Eunucos e párias, (pessoas) que nasceram cegas ou surdas, os insanos, idiotas e os mudos, bem como aqueles deficientes em qualquer órgão (de ação ou sensação), não recebem parte.` },
        { id: 'cm-9-202', number: 'Verso 202', text: `Mas é justo que (um homem) que conhece (a lei) deva dar até mesmo a todos eles comida e roupas sem restrições, de acordo com a sua capacidade; aquele que não o der tornar-se-á um pária.` },
        { id: 'cm-9-203', number: 'Verso 203', text: `Se o eunuco e os restantes de alguma forma desejarem (tomar) esposas, a prole de tais entre eles que tenham filhos é digna de uma parte.` },
        { id: 'cm-9-204', number: 'Verso 204', text: `Qualquer propriedade que o (filho) mais velho adquira (pelo seu próprio esforço) após a morte do pai, uma parte disso (pertencerá) aos seus (irmãos) mais novos, desde que tenham feito um devido progresso no aprendizado.` },
        { id: 'cm-9-205', number: 'Verso 205', text: `Mas se todos eles, sendo ignorantes, adquirirem propriedade pelo seu trabalho, a divisão disso será igual, (pois) não é propriedade adquirida pelo pai; essa é uma regra estabelecida.` },
        { id: 'cm-9-206', number: 'Verso 206', text: `Propriedade (adquirida) pelo aprendizado pertence unicamente àquele a quem (foi dada), da mesma forma o presente de um amigo, um presente recebido no casamento ou com a mistura de mel.` },
        { id: 'cm-9-207', number: 'Verso 207', text: `Mas se um dos irmãos, sendo capaz (de se sustentar) por sua própria ocupação, não desejar (uma parte da propriedade da família), ele pode ser separado (pelos outros) recebendo uma ninharia da sua parte para viver.` },
        { id: 'cm-9-208', number: 'Verso 208', text: `O que um (irmão) puder adquirir pelo seu trabalho sem usar o patrimônio, essa aquisição, (feita unicamente) pelo seu próprio esforço, ele não partilhará a não ser por sua própria vontade (com os seus irmãos).` },
        { id: 'cm-9-209', number: 'Verso 209', text: `Mas se um pai recupera propriedade ancestral perdida, ele não a dividirá, a não ser por sua própria vontade, com os seus filhos, (pois é) propriedade auto-adquirida.` },
        { id: 'cm-9-210', number: 'Verso 210', text: `Se irmãos, (uma vez) divididos e vivendo (novamente) juntos (como coproprietários), fizerem uma segunda partilha, a divisão será nesse caso igual; em tal caso não há direito de primogenitura.` },
        { id: 'cm-9-211', number: 'Verso 211', text: `Se o (irmão) mais velho ou o mais novo for privado da sua parte, ou se um deles morrer, a sua parte não é perdida (para os seus herdeiros imediatos).` },
        { id: 'cm-9-212', number: 'Verso 212', text: `Os seus irmãos uterinos, tendo-se reunido, a dividirão igualmente, e aqueles irmãos que foram reunidos (com ele) e as irmãs uterinas.` },
        { id: 'cm-9-213', number: 'Verso 213', text: `Um irmão mais velho que através da avareza possa defraudar os mais novos, não deverá mais (ocupar a posição de) mais velho, não receberá uma parte (adicional de filho mais velho), e será punido pelo rei.` },
        { id: 'cm-9-214', number: 'Verso 214', text: `Todos os irmãos que habitualmente cometem atos proibidos são indignos de (uma parte da) propriedade, e o mais velho não fará (nada ser sua) propriedade separada sem dar (um equivalente) aos seus irmãos mais novos.` },
        { id: 'cm-9-215', number: 'Verso 215', text: `Se irmãos não divididos, (vivendo com o seu pai,) fizerem juntos um esforço (para ganho), o pai não deverá, de forma alguma, dar-lhes partes desiguais (numa divisão da propriedade).` },
        { id: 'cm-9-216', number: 'Verso 216', text: `Mas um filho, nascido após a partilha, deverá sozinho tomar a propriedade de seu pai, ou se algum (dos outros filhos) for reunido com o (pai), ele deverá partilhar com eles.` },
        { id: 'cm-9-217', number: 'Verso 217', text: `Uma mãe obterá a herança de um filho (que morre) sem deixar descendência, e, se a mãe estiver morta, a avó paterna tomará a propriedade.` },
        { id: 'cm-9-218', number: 'Verso 218', text: `E se, após todas as dívidas e ativos terem sido devidamente distribuídos de acordo com a regra, qualquer (propriedade) for posteriormente descoberta, deve-se dividi-la igualmente.` },
        { id: 'cm-9-219', number: 'Verso 219', text: `Um vestido, um veículo, ornamentos, comida cozida, água e (escravas) fêmeas, propriedade destinada a usos piedosos ou sacrifícios, e um pasto, eles declaram ser indivisíveis.` },
        { id: 'cm-9-220', number: 'Verso 220', text: `A divisão (da propriedade) e as regras para alocar (partes) aos (vários) filhos, àqueles gerados numa esposa e os restantes, na ordem (devida), foram assim declaradas a vós; ouçam (agora) as leis relativas aos jogos de azar.` },
        { id: 'cm-9-221', number: 'Verso 221', text: `Jogos de azar e apostas que o rei exclua do seu reino; esses dois vícios causam a destruição dos reinos dos príncipes.` },
        { id: 'cm-9-222', number: 'Verso 222', text: `Jogos de azar e apostas equivalem a roubo aberto; o rei deve sempre esforçar-se para suprimir ambos.` },
        { id: 'cm-9-223', number: 'Verso 223', text: `Quando (coisas) inanimadas são usadas (para apostar dinheiro nelas), isso é chamado entre os homens de jogo de azar (*dyuta*), quando seres animados são usados (para o mesmo propósito), deve-se saber que isso é aposta (*samahvaya*).` },
        { id: 'cm-9-224', number: 'Verso 224', text: `Que o rei puna corporalmente todas aquelas (pessoas) que jogam ou apostam, ou que oferecem (uma oportunidade para isso), da mesma forma os *Sudras* que assumem as marcas distintivas dos (homens) duas vezes nascidos.` },
        { id: 'cm-9-225', number: 'Verso 225', text: `Jogadores, dançarinos e cantores, homens cruéis, homens pertencentes a uma seita herética, aqueles que seguem ocupações proibidas, e vendedores de bebidas alcoólicas, que ele os bana instantaneamente da sua cidade.` },
        { id: 'cm-9-226', number: 'Verso 226', text: `Se tais (pessoas que são) ladrões secretos, habitarem no reino de um rei, elas assediam constantemente os seus bons súditos pelas suas práticas proibidas.` },
        { id: 'cm-9-227', number: 'Verso 227', text: `Num *Kalpa* anterior, este (vício de) jogo foi visto como causa de grande inimizade; um homem sábio, portanto, não deveria praticá-lo nem mesmo para diversão.` },
        { id: 'cm-9-228', number: 'Verso 228', text: `Sobre todo o homem que se entrega a esse (vício) seja secreta ou abertamente, o rei pode infligir punição de acordo com a sua discrição.` },
        { id: 'cm-9-229', number: 'Verso 229', text: `Mas um *Kshatriya*, um *Vaisya* e um *Sudra* que são incapazes de pagar uma multa, quitarão a dívida com trabalho; um *Brahmana* deverá pagá-la em parcelas.` },
        { id: 'cm-9-230', number: 'Verso 230', text: `Em mulheres, crianças, homens de mente perturbada, os pobres e os doentes, o rei deverá infligir punição com um chicote, uma bengala, ou uma corda e semelhantes.` },
        { id: 'cm-9-231', number: 'Verso 231', text: `Mas aqueles nomeados (para administrar) assuntos (públicos), que, assados pelo fogo da riqueza, arruínam os negócios dos pretendentes, o rei deverá privar das suas propriedades.` },
        { id: 'cm-9-232', number: 'Verso 232', text: `Falsificadores de éditos reais, aqueles que corrompem os seus ministros, aqueles que matam mulheres, crianças ou *Brahmanas*, e aqueles que serveem os seus inimigos, o rei deverá condenar à morte.` },
        { id: 'cm-9-233', number: 'Verso 233', text: `Sempre que qualquer (transação legal) tiver sido concluída ou (uma punição) tiver sido infligida de acordo com a lei, ele deverá sancioná-la e não anulá-la.` },
        { id: 'cm-9-234', number: 'Verso 234', text: `Qualquer assunto que os seus ministros ou o juiz possam resolver de forma inadequada, que o próprio rei (re)solva e multe-(os) em mil (*panas*).` },
        { id: 'cm-9-235', number: 'Verso 235', text: `O assassino de um *Brahmana*, (Um homem duas vezes nascido) que bebe (a bebida alcoólica chamada) *Sura*, aquele que rouba (o ouro de um *Brahmana*), e aquele que viola a cama de um Guru, devem todos ser considerados como homens que cometeram pecados mortais (*mahapataka*).` },
        { id: 'cm-9-236', number: 'Verso 236', text: `Mesmo sobre esses quatro, se não realizarem uma penitência, que ele inflija punição corporal e multas de acordo com a lei.` },
        { id: 'cm-9-237', number: 'Verso 237', text: `Por violar a cama de um Guru, (a marca de) uma parte feminina será (impressa na testa com um ferro quente); por beber (a bebida alcoólica chamada) *Sura*, o sinal de uma taverna; por roubar (o ouro de um *Brahmana*), um pé de cachorro; por assassinar um *Brahmana*, um cadáver sem cabeça.` },
        { id: 'cm-9-238', number: 'Verso 238', text: `Excluídos de toda companhia nas refeições, excluídos de todos os sacrifícios, excluídos da instrução e de alianças matrimoniais, abjetos e excluídos de todos os deveres religiosos, que eles vaguem por (esta) terra.` },
        { id: 'cm-9-239', number: 'Verso 239', text: `Tais (pessoas) que foram marcadas a fogo com marcas (indelével) devem ser rejeitadas pelos seus parentes paternos e maternos, e não receber nem compaixão nem uma saudação; esse é o ensinamento de Manu.` },
        { id: 'cm-9-240', number: 'Verso 240', text: `Mas (homens de) todas as castas que realizam as penitências prescritas, não devem ser marcados a fogo na testa pelo rei, mas deverão ser forçados a pagar a maior penalidade.` },
        { id: 'cm-9-241', number: 'Verso 241', text: `Por (tais) ofensas a penalidade intermediária será infligida a um *Brahmana*, ou ele poderá ser banido do reino, mantendo o seu dinheiro e os seus bens.` },
        { id: 'cm-9-242', number: 'Verso 242', text: `Mas (homens de) outras (castas), que cometeram involuntariamente tais crimes, devem ser privados de toda a sua propriedade; se (os cometeram) intencionalmente, serão banidos.` },
        { id: 'cm-9-243', number: 'Verso 243', text: `Um rei virtuoso não deve tomar para si a propriedade de um homem culpado de pecado mortal; mas se ele a toma por ganância, ele é manchado por essa culpa (do ofensor).` },
        { id: 'cm-9-244', number: 'Verso 244', text: `Tendo lançado tal multa na água, que ele a ofereça a *Varuna*, ou que a conceda a um *Brahmana* erudito e virtuoso.` },
        { id: 'cm-9-245', number: 'Verso 245', text: `*Varuna* é o senhor da punição, pois ele detém o cetro até mesmo sobre os reis; um *Brahmana* que aprendeu todo o Veda é o senhor do mundo inteiro.` },
        { id: 'cm-9-246', number: 'Verso 246', text: `Naquele (país), onde o rei evita tomar a propriedade dos pecadores (mortais), os homens nascem no tempo (devido e são) longevos,` },
        { id: 'cm-9-247', number: 'Verso 247', text: `E as colheitas dos lavradores brotam, cada uma como foi semeada, e as crianças não morrem, e nenhuma (prole) deformada nasce.` },
        { id: 'cm-9-248', number: 'Verso 248', text: `Mas o rei deverá infligir a um (Sudra) de baixo nascimento, que intencionalmente causa dor aos *Brahmanas*, vários (tipos de) punição corporal que causem terror.` },
        { id: 'cm-9-249', number: 'Verso 249', text: `Quando um rei pune um (homem) inocente, a sua culpa é considerada tão grande quanto quando ele liberta um homem culpado; mas (ele adquire) mérito quando pune (justamente).` },
        { id: 'cm-9-250', number: 'Verso 250', text: `Assim foi declarada extensamente a (maneira de) decidir ações judiciais (que se enquadram) sob os dezoito títulos, entre duas partes litigantes.` },
        { id: 'cm-9-251', number: 'Verso 251', text: `Um rei que assim cumpre devidamente os seus deveres de acordo com a justiça, pode procurar ganhar países que ainda não ganhou, e deverá protegê-los devidamente quando os tiver ganho.` },
        { id: 'cm-9-252', number: 'Verso 252', text: `Tendo assentado devidamente o seu país, e tendo construído fortes de acordo com os Institutos, ele deverá usar os seus maiores esforços para remover (aqueles homens que são nocivos como) espinhos.` },
        { id: 'cm-9-253', number: 'Verso 253', text: `Protegendo aqueles que vivem como (convém) aos Arianos e removendo os espinhos, os reis, unicamente com a intenção de proteger os seus súditos, alcançam o céu.` },
        { id: 'cm-9-254', number: 'Verso 254', text: `O reino daquele rei que toma a sua parte em espécie, embora não puna os ladrões, (será) perturbado e ele (perderá) o céu.` },
        { id: 'cm-9-255', number: 'Verso 255', text: `Mas se o seu reino for seguro, protegido pela força do seu braço, florescerá constantemente como uma árvore (bem) regada.` },
        { id: 'cm-9-256', number: 'Verso 256', text: `Que o rei que vê (tudo) através dos seus espiões, descubra os dois tipos de ladrões que privam os outros das suas propriedades, tanto aqueles que se (mostram) abertamente quanto aqueles que (ficam) escondidos.` },
        { id: 'cm-9-257', number: 'Verso 257', text: `Entre eles, os patifes abertos (são aqueles) que subsistem por (trapacear na venda de) várias mercadorias comercializáveis, mas os patifes escondidos são arrombadores, assaltantes em florestas, e assim por diante.` },
        { id: 'cm-9-258', number: 'Verso 258', text: `Aqueles que aceitam subornos, trapaceiros e patifes, jogadores, aqueles que vivem ensinando (a realização de) cerimônias auspiciosas, hipócritas santimoniosos e cartomantes,` },
        { id: 'cm-9-259', number: 'Verso 259', text: `Funcionários de alta patente e médicos que agem de forma inadequada, homens que vivem mostrando a sua proficiência nas artes e prostitutas espertas,` },
        { id: 'cm-9-260', number: 'Verso 260', text: `Estes e semelhantes que se mostram abertamente, bem como outros que andam disfarçados (como) não-arianos que usam as marcas dos Arianos, ele deveria saber que são espinhos (no lado do seu povo).` },
        { id: 'cm-9-261', number: 'Verso 261', text: `Tendo-os detectado por meio de pessoas de confiança, que, disfarçando-se, (fingem) seguir as mesmas ocupações e por meio de espiões, usando vários disfarces, ele deve fazer com que sejam instigados (a cometer ofensas) e trazê-los para o seu poder.` },
        { id: 'cm-9-262', number: 'Verso 262', text: `Então, tendo feito com que os crimes, que eles cometeram pelas suas diversas ações, sejam proclamados de acordo com os fatos, o rei deverá puni-los devidamente de acordo com a sua força e os seus crimes.` },
        { id: 'cm-9-263', number: 'Verso 263', text: `Pois a maldade de ladrões mal-intencionados, que rondam secretamente por esta terra, não pode ser contida exceto pela punição.` },
        { id: 'cm-9-264', number: 'Verso 264', text: `Casas de assembleia, casas onde a água é distribuída ou bolos são vendidos, bordéis, tavernas e lojas de vitualhas, encruzilhadas, árvores conhecidas, assembleias festivas, teatros e salas de concerto,` },
        { id: 'cm-9-265', number: 'Verso 265', text: `Jardins antigos, florestas, lojas de artesãos, moradias vazias, bosques naturais e artificiais,` },
        { id: 'cm-9-266', number: 'Verso 266', text: `Nestes e locais semelhantes o rei deverá mandar guardar por companhias de soldados, tanto estacionárias quanto em patrulha, e por espiões, a fim de manter os ladrões afastados.` },
        { id: 'cm-9-267', number: 'Verso 267', text: `Por meio de espertos ladrões reformados, que se associam a tais (patifes), os seguem e conhecem as suas várias maquinações, ele deve detectá-los e destruí-los.` },
        { id: 'cm-9-268', number: 'Verso 268', text: `Sob o pretexto de (oferecer a eles) várias iguarias, de apresentá-los a *Brahmanas*, e com a desculpa de (mostrar a eles) proezas de força, os (espiões) devem fazê-los encontrar (os oficiais de justiça).` },
        { id: 'cm-9-269', number: 'Verso 269', text: `Aqueles entre eles que não vêm, e aqueles que suspeitam dos velhos (ladrões empregados pelo rei), o rei deverá atacar pela força e matar juntamente com os seus amigos, parentes de sangue e conexões.` },
        { id: 'cm-9-270', number: 'Verso 270', text: `Um rei justo não fará com que um ladrão seja condenado à morte, (a menos que seja pego) com os bens roubados (em sua posse); aquele que (é pego) com os bens roubados e os implementos (de roubo), ele pode, sem hesitação, mandar matar.` },
        { id: 'cm-9-271', number: 'Verso 271', text: `Todos aqueles também que nas aldeias dão comida a ladrões ou concedem-lhes espaço para (esconder os seus implementos), ele fará com que sejam mortos.` },
        { id: 'cm-9-272', number: 'Verso 272', text: `Aqueles que são nomeados para guardar províncias e os seus vassalos que receberam ordens (para ajudar), ele deverá punir rapidamente como ladrões, (se permanecerem) inativos em ataques (de ladrões).` },
        { id: 'cm-9-273', number: 'Verso 273', text: `Além disso, se (um homem), que subsiste pelo (cumprimento da) lei, se afasta da regra estabelecida da lei, o (rei) deverá puni-lo severamente com uma multa, (porque ele) violou o seu dever.` },
        { id: 'cm-9-274', number: 'Verso 274', text: `Aqueles que não prestam assistência de acordo com as suas capacidades quando uma aldeia está a ser saqueada, um dique está a ser destruído ou um roubo na estrada cometido, serão banidos com os seus bens e pertences.` },
        { id: 'cm-9-275', number: 'Verso 275', text: `Sobre aqueles que roubam o tesouro do rei e aqueles que perseveram em se opor (aos seus comandos), ele infligirá vários tipos de pena capital, bem como sobre aqueles que conspiram com os seus inimigos.` },
        { id: 'cm-9-276', number: 'Verso 276', text: `Mas o rei cortará as mãos daqueles ladrões que, arrombando casas, cometem roubos à noite, e fará com que sejam empalados numa estaca pontiaguda.` },
        { id: 'cm-9-277', number: 'Verso 277', text: `Na primeira condenação, que ele mande amputar dois dedos de um batedor de carteiras; na segunda, uma mão e um pé; na terceira, ele sofrerá a morte.` },
        { id: 'cm-9-278', number: 'Verso 278', text: `Aqueles que dão (aos ladrões) fogo, comida, armas ou abrigo, e os receptadores de bens roubados, o governante punirá como ladrões.` },
        { id: 'cm-9-279', number: 'Verso 279', text: `Aquele que quebrar (a represa de) um tanque ele matará (afogando-o) na água ou por (algum outro) (modo de) punição capital; ou o ofensor pode reparar o (dano), mas será forçado a pagar a penalidade mais alta.` },
        { id: 'cm-9-280', number: 'Verso 280', text: `Aqueles que arrombam um armazém (real), um arsenal ou um templo, e aqueles que roubam elefantes, cavalos ou carruagens, ele matará sem hesitação.` },
        { id: 'cm-9-281', number: 'Verso 281', text: `Mas aquele que tirar a água de um tanque, feito nos tempos antigos, ou cortar o suprimento de água, deve ser obrigado a pagar a primeira (ou menor) penalidade.` },
        { id: 'cm-9-282', number: 'Verso 282', text: `Mas aquele que, exceto num caso de extrema necessidade, deixar cair imundície na estrada principal do rei, pagará dois *karshapanas* e removerá imediatamente (essa) imundície.` },
        { id: 'cm-9-283', number: 'Verso 283', text: `Mas uma pessoa em necessidade urgente, um homem idoso, uma mulher grávida ou uma criança, deverá ser repreendida e limpar o (local); essa é uma regra estabelecida.` },
        { id: 'cm-9-284', number: 'Verso 284', text: `Todos os médicos que tratam (os seus pacientes) erroneamente (pagarão) uma multa; no caso de animais, a primeira (ou menor); no caso de seres humanos, a (penalidade) intermediária.` },
        { id: 'cm-9-285', number: 'Verso 285', text: `Aquele que destrói uma ponte, a bandeira (de um templo ou palácio real), um mastro, ou imagens, reparará todo o (dano) e pagará quinhentos (*panas*).` },
        { id: 'cm-9-286', number: 'Verso 286', text: `Por adulterar mercadorias não adulteradas, e por quebrar gemas ou por perfurá-las indevidamente, a multa é a primeira (ou menor) penalidade.` },
        { id: 'cm-9-287', number: 'Verso 287', text: `Mas o homem que se comporta desonestamente com (clientes) honestos ou trapaceia nos seus preços, será multado na primeira ou na penalidade intermediária.` },
        { id: 'cm-9-288', number: 'Verso 288', text: `Que ele coloque todas as prisões perto de uma estrada principal, onde os infratores sofredores e desfigurados possam ser vistos.` },
        { id: 'cm-9-289', number: 'Verso 289', text: `Aquele que destruir a muralha (de uma cidade), ou preencher o fosso (em volta de uma cidade), ou quebrar um portão (da cidade), ele banirá instantaneamente.` },
        { id: 'cm-9-290', number: 'Verso 290', text: `Por todos os encantamentos destinados a destruir a vida, por ritos mágicos com raízes (praticados por pessoas) não parentes (àquele contra quem são dirigidos), e por vários tipos de feitiçaria, uma multa de duzentos (*panas*) será infligida.` },
        { id: 'cm-9-291', number: 'Verso 291', text: `Aquele que vende (como semente-grão aquilo que) não é semente-grão, aquele que recolhe a semente (já semeada), e aquele que destrói uma (marca de) limite, será punido com mutilação.` },
        { id: 'cm-9-292', number: 'Verso 292', text: `Mas o rei fará com que um ourives que se comporte desonestamente, o mais nocivo de todos os espinhos, seja cortado em pedaços com navalhas.` },
        { id: 'cm-9-293', number: 'Verso 293', text: `Pelo roubo de implementos agrícolas, de armas e de medicamentos, que o rei conceda punição, levando em conta o momento (da ofensa) e o uso (do objeto).` },
        { id: 'cm-9-294', number: 'Verso 294', text: `O rei e o seu ministro, a sua capital, o seu reino, o seu tesouro, o seu exército e o seu aliado são as sete partes constituintes (de um reino); (daí) diz-se que um reino tem sete membros (*anga*).` },
        { id: 'cm-9-295', number: 'Verso 295', text: `Mas que ele saiba (que) entre essas sete partes constituintes de um reino (que foram enumeradas) em ordem, cada uma (nomeada) anteriormente é mais importante e (a sua destruição) a maior calamidade.` },
        { id: 'cm-9-296', number: 'Verso 296', text: `No entanto, num reino contendo sete partes constituintes, que é sustentado como o cajado triplo (de um asceta), não há (nenhuma parte) mais importante (do que as outras), em razão da importância das qualidades de cada uma para as outras.` },
        { id: 'cm-9-297', number: 'Verso 297', text: `Pois cada parte é particularmente qualificada para (a realização de) certos objetivos, (e assim) cada uma é declarada a mais importante para aquele propósito particular que é efetuado pelos seus meios.` },
        { id: 'cm-9-298', number: 'Verso 298', text: `Por espiões, por uma exibição (fingida) de energia, e pela execução de (várias) empreitadas, que o rei certifique-se constantemente da sua própria força e da do seu inimigo;` },
        { id: 'cm-9-299', number: 'Verso 299', text: `Além disso, todas as calamidades e vícios; depois, quando tiver considerado plenamente a sua importância relativa, que ele inicie as suas operações.` },
        { id: 'cm-9-300', number: 'Verso 300', text: `(Mesmo que ele esteja) muito cansado (por falhas repetidas), que ele inicie as suas operações de novo e de novo; pois a fortuna favorece muito o homem que (vigorosamente) se esforça nas suas empreitadas.` },
        { id: 'cm-9-301', number: 'Verso 301', text: `As várias maneiras pelas quais um rei se comporta (assemelham-se) às eras *Krita*, *Treta*, *Dvapara* e *Kali*; daí que o rei se identifique com as eras (do mundo).` },
        { id: 'cm-9-302', number: 'Verso 302', text: `Dormindo ele representa o *Kali* (ou idade do ferro), acordando a idade *Dvapara* (ou de bronze), pronto para agir a *Treta* (ou idade de prata), mas movendo-se (ativamente) a era *Krita* (ou de ouro).` },
        { id: 'cm-9-303', number: 'Verso 303', text: `Que o rei emule a ação enérgica de *Indra*, do Sol, do Vento, de *Yama*, de *Varuna*, da Lua, do Fogo e da Terra.` },
        { id: 'cm-9-304', number: 'Verso 304', text: `Como *Indra* envia chuva copiosa durante os quatro meses da estação das chuvas, da mesma forma que o rei, assumindo o cargo de *Indra*, derrame benefícios sobre o seu reino.` },
        { id: 'cm-9-305', number: 'Verso 305', text: `Como o Sol durante oito meses atrai (imperceptivelmente) a água com os seus raios, da mesma forma que ele atraia gradualmente os seus impostos do seu reino; pois esse é o ofício em que se assemelha ao Sol.` },
        { id: 'cm-9-306', number: 'Verso 306', text: `Como o Vento se move (por toda parte), entrando (na forma do ar vital) em todos os seres criados, da mesma forma que ele penetre (por toda parte) através dos seus espiões; esse é o ofício em que se assemelha ao Vento.` },
        { id: 'cm-9-307', number: 'Verso 307', text: `Como *Yama* no momento determinado sujeita ao seu governo tanto amigos quanto inimigos, da mesma forma todos os súditos devem ser controlados pelo rei; esse é o ofício em que se assemelha a *Yama*.` },
        { id: 'cm-9-308', number: 'Verso 308', text: `Como (um pecador) é visto amarrado com cordas por *Varuna*, da mesma forma que ele puna os ímpios; esse é o seu ofício em que se assemelha a *Varuna*.` },
        { id: 'cm-9-309', number: 'Verso 309', text: `Ele é um rei, assumindo o ofício da Lua, cuja (aparência) os seus súditos (saúdam com alegria tão grande) quanto os homens sentem ao ver a lua cheia.` },
        { id: 'cm-9-310', number: 'Verso 310', text: `(Se) ele é ardente em ira contra os criminosos e dotado de energia brilhante, e destrói vassalos perversos, então o seu caráter é dito (assemelhar-se) ao do Fogo.` },
        { id: 'cm-9-311', number: 'Verso 311', text: `Como a Terra suporta todos os seres criados igualmente, assim (um rei) que sustenta todos os seus súditos, (assume para si) o cargo da Terra.` },
        { id: 'cm-9-312', number: 'Verso 312', text: `Empregando esses e outros meios, o rei deverá, sempre incansável, conter os ladrões tanto nos seus próprios domínios quanto (nos) de outros.` },
        { id: 'cm-9-313', number: 'Verso 313', text: `Que ele não provoque a ira dos *Brahmanas*, mesmo tendo caído na mais profunda angústia; pois eles, quando irritados, poderiam destruí-lo instantaneamente juntamente com o seu exército e os seus veículos.` },
        { id: 'cm-9-314', number: 'Verso 314', text: `Quem poderia escapar da destruição, ao provocar a ira daqueles (homens), por quem o fogo foi feito para consumir todas as coisas, por quem a (água do) oceano foi feita intragável, e por quem a lua foi feita minguar e aumentar novamente?` },
        { id: 'cm-9-315', number: 'Verso 315', text: `Quem poderia prosperar, enquanto fere àqueles (homens) que provocados à ira, poderiam criar outros mundos e outros guardiões do mundo, e privar os deuses de sua posição divina?` },
        { id: 'cm-9-316', number: 'Verso 316', text: `Qual homem, desejoso de vida, feriria aqueles a cujo apoio os (três) mundos e os deuses sempre devem a sua existência, e cuja riqueza é o Veda?` },
        { id: 'cm-9-317', number: 'Verso 317', text: `Um *Brahmana*, seja ele ignorante ou erudito, é uma grande divindade, assim como o fogo, quer levado adiante (para a realização de uma oblação queimada) ou não levado adiante, é uma grande divindade.` },
        { id: 'cm-9-318', number: 'Verso 318', text: `O fogo brilhante não é contaminado nem mesmo em cemitérios e, quando apresentado com oblações (de manteiga) em sacrifícios, aumenta novamente com poder.` },
        { id: 'cm-9-319', number: 'Verso 319', text: `Assim, embora os *Brahmanas* se empreguem em todos (os tipos de) ocupações inferiores, devem ser honrados de todas as maneiras; pois (cada um) deles é uma divindade muito grande.` },
        { id: 'cm-9-320', number: 'Verso 320', text: `Quando os *Kshatriyas* se tornam de alguma forma dominadores em relação aos *Brahmanas*, os próprios *Brahmanas* deverão contê-los devidamente; pois os *Kshatriyas* brotaram dos *Brahmanas*.` },
        { id: 'cm-9-321', number: 'Verso 321', text: `O Fogo brotou da água, os *Kshatriyas* dos *Brahmanas*, o ferro da pedra; a força penetrante desses (três) não tem efeito naquilo de onde foram produzidos.` },
        { id: 'cm-9-322', number: 'Verso 322', text: `Os *Kshatriyas* não prosperam sem os *Brahmanas*, os *Brahmanas* não prosperam sem os *Kshatriyas*; *Brahmanas* e *Kshatriyas*, estando intimamente unidos, prosperam neste (mundo) e no próximo.` },
        { id: 'cm-9-323', number: 'Verso 323', text: `Mas (um rei que sente o seu fim aproximar-se) deverá conceder toda a sua riqueza, acumulada de multas, aos *Brahmanas*, entregar o seu reino ao seu filho e então procurar a morte na batalha.` },
        { id: 'cm-9-324', number: 'Verso 324', text: `Assim conduzindo-se (e) sempre focado em (cumprir) os seus deveres reais, um rei ordenará que todos os seus servos (trabalhem) para o bem do seu povo.` },
        { id: 'cm-9-325', number: 'Verso 325', text: `Assim a lei eterna relativa aos deveres de um rei foi totalmente declarada; saiba que as regras seguintes se aplicam na (devida) ordem aos deveres dos *Vaisyas* e *Sudras*.` },
        { id: 'cm-9-326', number: 'Verso 326', text: `Depois que um *Vaisya* recebeu os sacramentos e tomou uma esposa, ele deverá estar sempre atento aos negócios com os quais possa subsistir e ao (de) cuidar do gado.` },
        { id: 'cm-9-327', number: 'Verso 327', text: `Pois quando o Senhor das criaturas (*Pragapati*) criou o gado, entregou-o ao *Vaisya*; ao *Brahmana* e ao rei ele confiou todos os seres criados.` },
        { id: 'cm-9-328', number: 'Verso 328', text: `Um *Vaisya* nunca deve (conceber este) desejo: 'Não criarei gado'; e se um *Vaisya* estiver disposto (a criá-los), eles nunca devem ser criados por (homens de) outras (castas).` },
        { id: 'cm-9-329', number: 'Verso 329', text: `(Um *Vaisya*) deve saber o respectivo valor de pedras preciosas, de pérolas, de coral, de metais, de (tecidos) feitos de fios, de perfumes e de condimentos.` },
        { id: 'cm-9-330', number: 'Verso 330', text: `Ele deve estar familiarizado com a (maneira de) semeadura de sementes, e com as boas e más qualidades dos campos, e deve conhecer perfeitamente todas as medidas e pesos.` },
        { id: 'cm-9-331', number: 'Verso 331', text: `Além disso, a excelência e os defeitos das mercadorias, as vantagens e desvantagens de (diferentes) países, o lucro e a perda (prováveis) na mercadoria, e os meios de criar o gado de forma adequada.` },
        { id: 'cm-9-332', number: 'Verso 332', text: `Ele deve estar familiarizado com os salários (adequados) dos servos, com as várias linguagens dos homens, com a maneira de guardar os bens, e (as regras de) compra e venda.` },
        { id: 'cm-9-333', number: 'Verso 333', text: `Que ele se esforce ao máximo para aumentar a sua propriedade de maneira justa, e que dê comida zelosamente a todos os seres criados.` },
        { id: 'cm-9-334', number: 'Verso 334', text: `Mas servir aos *Brahmanas* (que são) eruditos nos Vedas, chefes de família, e famosos (pela virtude) é o maior dever de um *Sudra*, que leva à bem-aventurança.` },
        { id: 'cm-9-335', number: 'Verso 335', text: `(Um *Sudra* que é) puro, servo dos seus superiores, gentil na sua fala, livre de orgulho e que sempre busca refúgio com os *Brahmanas*, alcança (na sua próxima vida) uma casta superior.` },
        { id: 'cm-9-336', number: 'Verso 336', text: `A excelente lei para a conduta das (quatro) castas (*varna*), (quando elas) não (estão) em angústia, foi assim promulgada; agora ouçam em ordem os seus (vários deveres) em tempos de angústia.` },
      ],
    },
  ],
};
